changeSet.sql:
-- A session holding a lock on a retired table (an operator's idle transaction on the recovery source) fails the
-- boot with a lock_not_available error after 120 s instead of hanging it; a role-level statement_timeout must not
-- kill the row count. Both revert at the end of the transaction (the vectors-030-1 settings).
SET LOCAL lock_timeout = '120s';
SET LOCAL statement_timeout = 0;

DO $drop$
DECLARE
    t text;
    n bigint;
BEGIN
    FOREACH t IN ARRAY ARRAY['chunks_retired_225', 'taxonomy_centroids_retired_225'] LOOP
        IF pg_catalog.to_regclass(pg_catalog.format('nexus.%I', t)) IS NOT NULL THEN
            EXECUTE pg_catalog.format('ALTER TABLE nexus.%I NO FORCE ROW LEVEL SECURITY', t);
            EXECUTE pg_catalog.format('SELECT pg_catalog.count(*) FROM nexus.%I', t) INTO n;
            RAISE NOTICE 'vectors-036-1: dropping nexus.% (% row(s))', t, n;
        END IF;
    END LOOP;
END
$drop$;

DROP TABLE IF EXISTS nexus.chunks_retired_225;
DROP TABLE IF EXISTS nexus.taxonomy_centroids_retired_225;

rollback.sql:
-- ROLLBACK: both retired tables, EMPTY, as vectors-030-1 leaves them (see the file header). A retired table that
-- already exists makes this fail, which is right: the state is not the one the rollback is for.
CREATE TABLE nexus.chunks_retired_225 (
    tenant_id       text NOT NULL,
    collection      text NOT NULL,
    chash           bytea NOT NULL,
    chunk_text      text,
    embedding_384   nexus.vector(384),
    embedding_768   nexus.vector(768),
    embedding_1024  nexus.vector(1024),
    chunk_tsv       tsvector GENERATED ALWAYS AS (pg_catalog.to_tsvector('english'::pg_catalog.regconfig, chunk_text)) STORED,
    metadata        jsonb NOT NULL DEFAULT '{}'::jsonb,
    created_at      timestamptz NOT NULL DEFAULT pg_catalog.now(),
    retention       text NOT NULL DEFAULT 'full',
    last_written_at timestamptz NOT NULL DEFAULT pg_catalog.now(),
    CONSTRAINT chunks_pk_retired_225 PRIMARY KEY (tenant_id, collection, chash),
    CONSTRAINT chunks_content_retention_consistent CHECK ((chunk_text IS NULL) = (retention = 'reference-only')),
    CONSTRAINT chunks_retention_chk CHECK (retention IN ('reference-only', 'full')),
    CONSTRAINT exactly_one_embedding CHECK (pg_catalog.num_nonnulls(embedding_384, embedding_768, embedding_1024) = 1)
);
-- CREATE TABLE ignores NOT VALID (it validates against zero rows), so the unvalidated octet check is added after.
ALTER TABLE nexus.chunks_retired_225
    ADD CONSTRAINT chunks_chash_octet_check CHECK (pg_catalog.octet_length(chash) = 32) NOT VALID;
CREATE INDEX idx_chunks_embedding_1024_retired_225 ON nexus.chunks_retired_225
    USING hnsw (embedding_1024 nexus.vector_cosine_ops) WITH (m = 16, ef_construction = 64);
CREATE INDEX idx_chunks_embedding_384_retired_225 ON nexus.chunks_retired_225
    USING hnsw (embedding_384 nexus.vector_cosine_ops) WITH (m = 16, ef_construction = 64);
CREATE INDEX idx_chunks_embedding_768_retired_225 ON nexus.chunks_retired_225
    USING hnsw (embedding_768 nexus.vector_cosine_ops) WITH (m = 16, ef_construction = 64);
CREATE INDEX idx_chunks_tenant_chash_retired_225 ON nexus.chunks_retired_225 USING btree (tenant_id, chash);
CREATE INDEX idx_chunks_trgm_retired_225 ON nexus.chunks_retired_225 USING gin (chunk_text nexus.gin_trgm_ops);
CREATE INDEX idx_chunks_tsv_retired_225 ON nexus.chunks_retired_225 USING gin (chunk_tsv);

CREATE TABLE nexus.taxonomy_centroids_retired_225 (
    tenant_id       text NOT NULL,
    collection      text NOT NULL,
    topic_id        bigint NOT NULL,
    embedding_384   nexus.vector(384),
    embedding_768   nexus.vector(768),
    embedding_1024  nexus.vector(1024),
    label           text NOT NULL,
    doc_count       integer,
    created_at      timestamptz NOT NULL DEFAULT pg_catalog.now(),
    CONSTRAINT taxonomy_centroids_pk_retired_225 PRIMARY KEY (tenant_id, collection, topic_id),
    CONSTRAINT taxonomy_centroids_exactly_one_embedding CHECK (pg_catalog.num_nonnulls(embedding_384, embedding_768, embedding_1024) = 1)
);
CREATE INDEX idx_taxonomy_centroids_embedding_1024_retired_225 ON nexus.taxonomy_centroids_retired_225
    USING hnsw (embedding_1024 nexus.vector_cosine_ops) WITH (m = 16, ef_construction = 64);
CREATE INDEX idx_taxonomy_centroids_embedding_384_retired_225 ON nexus.taxonomy_centroids_retired_225
    USING hnsw (embedding_384 nexus.vector_cosine_ops) WITH (m = 16, ef_construction = 64);
CREATE INDEX idx_taxonomy_centroids_embedding_768_retired_225 ON nexus.taxonomy_centroids_retired_225
    USING hnsw (embedding_768 nexus.vector_cosine_ops) WITH (m = 16, ef_construction = 64);

-- Row-level security: enabled and FORCEd, with the policies the pre-walk tables carried. vectors-030-1's
-- rollback does NO FORCE on the table it renames back, so FORCE must be on here.
ALTER TABLE nexus.chunks_retired_225 ENABLE ROW LEVEL SECURITY;
ALTER TABLE nexus.chunks_retired_225 FORCE ROW LEVEL SECURITY;
ALTER TABLE nexus.taxonomy_centroids_retired_225 ENABLE ROW LEVEL SECURITY;
ALTER TABLE nexus.taxonomy_centroids_retired_225 FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS tenant_isolation ON nexus.chunks_retired_225;
CREATE POLICY tenant_isolation ON nexus.chunks_retired_225
    USING (tenant_id = pg_catalog.current_setting('nexus.tenant', true))
    WITH CHECK (tenant_id = pg_catalog.current_setting('nexus.tenant', true));
DROP POLICY IF EXISTS chunks_gate_probe_owner_read ON nexus.chunks_retired_225;
CREATE POLICY chunks_gate_probe_owner_read ON nexus.chunks_retired_225 FOR SELECT TO CURRENT_USER USING (true);
DROP POLICY IF EXISTS tenant_isolation ON nexus.taxonomy_centroids_retired_225;
CREATE POLICY tenant_isolation ON nexus.taxonomy_centroids_retired_225
    USING (tenant_id = pg_catalog.current_setting('nexus.tenant', true))
    WITH CHECK (tenant_id = pg_catalog.current_setting('nexus.tenant', true));
